def reserve_many(stock, requested):
    for sku, qty in requested.items():
        if qty <= 0:
            raise ValueError("positive quantity required")
        if stock[sku] < qty:
            raise ValueError("insufficient stock")
        stock[sku] -= qty
    return dict(stock)


